{
  "title": "Distance at Constant Speed",
  "scope": "Understand how distance depends on speed and time under constant speed conditions.",
  "objectives": [
    {
      "id": "o1",
      "label": "Calculate distance from speed and time",
      "criterion": "The learner correctly applies the formula distance = speed × time, ensuring unit consistency between speed, time, and resulting distance.",
      "sourceIds": ["s1"]
    },
    {
      "id": "o2",
      "label": "Analyze proportionality of distance",
      "criterion": "The learner explains how doubling either speed or time affects the total distance proportionally.",
      "sourceIds": ["s1"]
    }
  ],
  "knowledge": "At constant speed, the relationship between distance, speed, and time is expressed as distance = speed × time. This means that distance is directly proportional to both speed and time. If time is doubled while speed remains constant, the distance traveled also doubles. Similarly, if speed is doubled while time is kept constant, the distance is doubled. It is critical that units match properly—for example, measuring speed in metres per second ($\\\\pu{m/s}$) and time in seconds ($\\\\pu{s}$) yields a distance in metres ($\\\\pu{m}$).",
  "concerns": [],
  "misconception": "Doubling both speed and time doubles the distance.",
  "misconceptionCorrection": "Doubling both speed and time actually quadruples the distance because distance is the product of speed and time, meaning each factor scales the result independently.",
  "opening": "I keep hearing that distance equals speed times time, but I am confused about how changing both speed and time at once changes the distance. Can you teach me how this works?",
  "transfer": {
    "question": "A rover on a distant planet travels at a constant speed of $\\\\pu{4 m/s}$ for $\\\\pu{25 s}$. If the rover's speed is increased to $\\\\pu{8 m/s}$ and it travels for $\\\\pu{50 s}$, what is the final distance traveled?",
    "expected": "To find the final distance, we use the formula distance = speed × time with the new values of speed (\\\\pu{8 m/s}) and time (\\\\pu{50 s}). Calculating this gives {{distance}} metres.",
    "criteria": [
      "The learner identifies the new speed and new time values.",
      "The learner multiplies the new speed by the new time correctly.",
      "The learner states the final unit as metres."
    ],
    "numeric": {
      "fields": [
        {
          "id": "distance",
          "label": "Final Distance",
          "unit": "m",
          "expected": 400,
          "tolerance": 0.1
        }
      ],
      "inputs": [
        {
          "id": "speed",
          "value": 8
        },
        {
          "id": "time",
          "value": 50
        }
      ],
      "code": "function calculate(inputs) { const distance = inputs.speed * inputs.time; return { metrics: { distance: distance } }; }"
    }
  },
  "board": {
    "title": "Constant Speed Explorer",
    "instruction": "Adjust the speed and time to see how the distance changes.",
    "assumptions": "Assume speed remains strictly constant during the travel time.",
    "state": [
